import { existsSync } from "node:fs";
import path from "node:path";
import { defineConfig } from "@playwright/test";
import { loadProjectSettingsSync, toPlaywrightProjects } from "./src/navmap-settings.js";
import { listProjectIds, PROJECTS_DIR, projectPaths } from "./src/project-paths.js";

// Specs generated by `npm run navmap:generate-tests` each call page.goto() with a full URL
// (a navmap can cover any host), so there's no single shared baseURL to configure here.
// Instead, every project with generated tests (projects/<id>/tests/) becomes one Playwright
// project per browser, configured from its projects/<id>/settings.json (the dashboard's Settings
// tab), with results kept in projects/<id>/test-results/. E.g.:
//   npx playwright test --project=www-saucedemo-com
const root = import.meta.dirname;
const projectIds = listProjectIds(root).filter((id) => existsSync(path.join(root, projectPaths(id).tests, "fixtures.ts")));

export default defineConfig({
  testDir: PROJECTS_DIR,
  projects: projectIds.flatMap((id) =>
    toPlaywrightProjects(id, loadProjectSettingsSync(root, id), path.join(root, projectPaths(id).tests)).map((p) => ({
      ...p,
      outputDir: path.join(root, projectPaths(id).testResults),
    })),
  ),
});
